// Aarunya Kids Preschool – simple Node app. Data in data/db.json, photos in uploads/ (private).
const express=require('express'),session=require('express-session'),multer=require('multer'),bcrypt=require('bcryptjs'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const DATA=process.env.DATA_DIR||__dirname;fs.mkdirSync(path.join(DATA,'data'),{recursive:true});const DB=path.join(DATA,'data/db.json'),UP=path.join(DATA,'uploads');fs.mkdirSync(UP,{recursive:true});
const HOMEVIDS=[['okigufBT-ws','Ganesha Nimajjanam 2026 @Aarunya Kids'],['Gb3wwVR2Rxk','Varalakshmi pooja celebration @ Aarunya kids'],['Lv5cinNre7E','Bead Threading Activity']]; // from the school YouTube channel
const YT='https://www.youtube.com/@AarunyaKidsPreschool';
const P='[PLACEHOLDER] ';
const IC={fb:'<svg viewBox="0 0 24 24" width=20 height=20 fill=currentColor><path d="M14 8h3V4h-3a4 4 0 0 0-4 4v2H7v4h3v8h4v-8h3l1-4h-4V8z"/></svg>',ig:'<svg viewBox="0 0 24 24" width=20 height=20 fill=none stroke=currentColor stroke-width=2><rect x=3 y=3 width=18 height=18 rx=5 /><circle cx=12 cy=12 r=4 /><circle cx=17.5 cy=6.5 r=1 fill=currentColor /></svg>',yt:'<svg viewBox="0 0 24 24" width=20 height=20><rect x=2 y=5 width=20 height=14 rx=4 fill=currentColor /><path d="M10 9l5 3-5 3z" fill="#e03131"/></svg>',g:'<svg viewBox="0 0 24 24" width=20 height=20 fill=none stroke=currentColor stroke-width=2><path d="M12 22s7-7 7-12a7 7 0 0 0-14 0c0 5 7 12 7 12z"/><circle cx=12 cy=10 r=2.5 /></svg>',m:'<svg viewBox="0 0 24 24" width=18 height=18 fill=none stroke=currentColor stroke-width=2><rect x=3 y=5 width=18 height=14 rx=2 /><path d="M3 7l9 6 9-6"/></svg>'};
const GMAPS='https://www.google.com/maps/place/Aarunya+Kids+preschool/@17.5135646,78.3752346,17z';
const mail=()=>{const m=db.daycare.email||'';return m?`<a class=mail href="mailto:${e(m)}">${IC.m} ${e(m)}</a>`:''};
const follow=()=>`<div class=follow><b>Follow us:</b> <a class="soc ig" href="https://www.instagram.com/aarunya_kids_preschool/" target=_blank rel=noopener>${IC.ig} Instagram</a><a class="soc yt" href="${YT}" target=_blank rel=noopener>${IC.yt} YouTube</a><a class="soc gg" href="${GMAPS}" target=_blank rel=noopener>${IC.g} Google</a>${db.daycare.facebook?`<a class="soc fb" href="${e(db.daycare.facebook)}" target=_blank rel=noopener>${IC.fb} Facebook</a>`:''}${waBtn()}</div>`;
const timesBox=()=>`<div class="card times"><h2>Our timings</h2>${db.daycare.schoolTime?`<p><b>School:</b> ${e(db.daycare.schoolTime)}</p>`:''}${db.daycare.daycareTime?`<p><b>Daycare:</b> ${e(db.daycare.daycareTime)}</p>`:''}${db.daycare.officeTime?`<p><b>Office:</b> ${e(db.daycare.officeTime)}</p>`:''}</div>`;
const hols=()=>(db.holidays||[]).filter(h=>/^\d{4}-\d{2}-\d{2}$/.test(h.date)).sort((a,b)=>a.date<b.date?-1:1);
const upcoming=(n,days)=>{const t=today(),lim=new Date(Date.parse(t)+days*864e5).toISOString().slice(0,10);return hols().filter(h=>h.date>=t&&h.date<=lim).slice(0,n)};
const upList=(L)=>L.length?`<ul class=uplist>${L.map(h=>`<li><span class=update>${nice(h.date)}</span> <b>${e(h.title)}</b>${h.note?` <small>${e(h.note)}</small>`:''}</li>`).join('')}</ul>`:'<p>No holidays listed yet.</p>';
const calBox=(y,m,o={})=>{const base=o.base||'/calendar';const pad=n=>String(n).padStart(2,'0');const first=new Date(Date.UTC(y,m-1,1)),days=new Date(Date.UTC(y,m,0)).getUTCDate(),lead=(first.getUTCDay()+6)%7,t=today();const H={};hols().forEach(h=>(H[h.date]=H[h.date]||[]).push(h.title));const pm=m===1?`${y-1}-12`:`${y}-${pad(m-1)}`,nm=m===12?`${y+1}-01`:`${y}-${pad(m+1)}`;let g='';for(let i=0;i<lead;i++)g+='<div class="calday empty"></div>';for(let d=1;d<=days;d++){const k=`${y}-${pad(m)}-${pad(d)}`,h=H[k];g+=`<div class="calday${h?' hol':''}${k===t?' today':''}"${h?` title="${e(h.join(', '))}"`:''}><span class=dn>${d}</span>${h?`<span class=ht>${e(h.join(', '))}</span>`:''}</div>`;}return `<div class="card cal"><div class=calhead><a class="btn b2" href="${base}?ym=${pm}${o.hash||''}">Prev</a><h3>${MON[m-1]} ${y}</h3><a class="btn b2" href="${base}?ym=${nm}${o.hash||''}">Next</a></div><div class=calgrid>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class=calwd>${x}</div>`).join('')}${g}</div><p class=calkey><span class="calday hol keybox"></span> School holiday <span class="calday today keybox"></span> Today</p></div>`};
const ymOf=q=>{const m=/^(\d{4})-(\d{2})$/.exec(q.query.ym||'');if(m&&+m[2]>=1&&+m[2]<=12)return[+m[1],+m[2]];const t=today();return[+t.slice(0,4),+t.slice(5,7)]};
const holSection=(q,base,hash)=>{const[y,m]=ymOf(q);return `<div class=holsec id=holidays><h2>Holiday calendar</h2>${calBox(y,m,{base,hash})}<div class="card"><h3>Upcoming holidays (next 90 days)</h3>${upList(upcoming(50,90))}</div></div>`};
const MON=['January','February','March','April','May','June','July','August','September','October','November','December'];
const nice=d=>{const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(d||'');return m?`${+m[3]} ${MON[+m[2]-1]} ${m[1]}`:e(d)};
const news=()=>[...db.announcements].sort((a,b)=>(b.pinned==='yes')-(a.pinned==='yes')||String(b.date).localeCompare(String(a.date)));
const newsCard=a=>`<div class="card news ${a.pinned==='yes'?'pinned':''}">${a.pinned==='yes'?'<span class=pin>Pinned</span>':''}<div class=date>${nice(a.date)}</div><h3>${e(a.title)}</h3><p class=pre>${e(a.body)}</p></div>`;
const noNews='<div class="card note"><b>No news right now.</b> Please check back soon, or follow us on Instagram and YouTube for updates.</div>';
const WA='https://wa.me/918688641056?text='+encodeURIComponent('Hello Aarunya Kids Preschool, I would like to enquire about admission / daycare for my child.');
const waBtn=()=>`<a class="soc wa" href="${WA}" target=_blank rel=noopener><svg viewBox="0 0 24 24" width=20 height=20 fill=currentColor><path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2zm0 18a8 8 0 0 1-4.1-1.1l-.3-.2-3 .8.8-2.9-.2-.3A8 8 0 1 1 12 20zm4.4-6c-.2-.1-1.4-.7-1.6-.8s-.4-.1-.5.1l-.7.9c-.1.2-.3.2-.5.1a6.5 6.5 0 0 1-3.2-2.8c-.2-.4.2-.4.7-1.3.1-.2 0-.3 0-.4l-.7-1.7c-.2-.5-.4-.4-.5-.4h-.5a1 1 0 0 0-.7.3 3 3 0 0 0-.9 2.2 5.2 5.2 0 0 0 1.1 2.8 11.9 11.9 0 0 0 4.6 4c1.7.7 2.4.8 3.2.6a2.8 2.8 0 0 0 1.8-1.3 2.3 2.3 0 0 0 .2-1.3c-.1-.1-.2-.2-.4-.3z"/></svg> Chat on WhatsApp</a>`;
const today=()=>new Date(Date.now()+330*6e4).toISOString().slice(0,10);
const sel=(n,opts,v)=>`<select name=${n}><option value="">-</option>${opts.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select>`;
const attFor=k=>{const rows=Object.keys(db.attendance).sort().reverse().filter(d=>db.attendance[d][k.id]).slice(0,14);return `<div class="card attbox"><h2>Attendance${rows.length?' (last '+rows.length+' days)':''}</h2>${rows.length?`<div class=attgrid>${rows.map(d=>`<div class="att ${db.attendance[d][k.id]==='Present'?'p':'a'}"><b>${db.attendance[d][k.id]}</b><span>${nice(d)}</span></div>`).join('')}</div>`:'<p>No attendance marked yet.</p>'}</div>`};
const addr=()=>db.daycare.address||'';
const phones=()=>(db.daycare.phones||'').split(',').map(x=>x.trim()).filter(Boolean);
const phoneLinks=()=>phones().map(p=>{const d=p.replace(/\D/g,'').slice(-10);return `<a class=tel href="tel:+91${d}">+91 ${d.slice(0,5)} ${d.slice(5)}</a>`}).join(' ');
const findUs=()=>{const a=encodeURIComponent(addr());const pin=(db.daycare.mapEmbed||`https://maps.google.com/maps?q=${a}&z=16&output=embed`);const open=db.daycare.mapLink||`https://www.google.com/maps/search/?api=1&query=${a}`;return `<div class="card findus"><h2>Find us</h2><p class=addr>${e(addr())}</p><p class=phones>Call us: ${phoneLinks()}</p><p>Email: ${mail()}</p>${follow()}<div class=map><iframe src="${pin}" title="Map of Aarunya Kids Preschool in Nizampet" loading=lazy referrerpolicy=no-referrer-when-downgrade allowfullscreen></iframe></div><p><a class="btn b2" href="${open}" target=_blank rel=noopener>Open in Google Maps</a></p></div>`};
function seed(){return{users:[{id:'u1',role:'admin',username:process.env.ADMIN_USERNAME||'Principal',name:'School Owner',pass:bcrypt.hashSync(process.env.ADMIN_PASSWORD||crypto.randomBytes(12).toString('hex'),8)},{id:'u2',role:'parent',username:'parent1',name:'Demo Parent',pass:bcrypt.hashSync('parent123',8)}],
announcements:[{id:'a1',title:P+'Welcome to the new school year!',body:'Example announcement. The owner can edit or delete this from the Admin page.',date:'2026-10-24'}],

uniforms:[{id:'n1',name:'School uniform',desc:'Photo coming soon.',photo:''}],
daycare:{timings:'Daycare: 8:30 AM to 6:30 PM',howto:"1. Call us on +91 86886 41056 or +91 97045 68440, email aarunyakidspreschool@gmail.com, or fill in the enquiry form below.\n2. Visit the school at Road No. 7, Venkatraya Nagar, Nizampet.\n3. Meet us to discuss your child's programme and fees in person.\n4. Complete the admission.",contact:'+91 86886 41056, +91 97045 68440',phones:'8688641056, 9704568440',email:'aarunyakidspreschool@gmail.com',facebook:'https://www.facebook.com/share/1A7gmaKYhu/',address:'Aarunya Kids Preschool, Road No. 7, Venkatraya Nagar, Nizampet, Hyderabad, Telangana 500090'},
kids:[{id:'k1',name:'Demo Child A',photo:'',parentId:'u2',contact:'',allergies:''},{id:'k2',name:'Demo Child B',photo:'',parentId:'u2',contact:'+91 00000 00000 (placeholder)',allergies:'None (placeholder)'}],
bookings:[]};}
let db=fs.existsSync(DB)?JSON.parse(fs.readFileSync(DB)):seed();const save=()=>fs.writeFileSync(DB,JSON.stringify(db,null,1));delete db.videos;if(!db.daycare.schoolTime){db.daycare.schoolTime='8:45 AM to 3:30 PM';db.daycare.daycareTime='8:30 AM to 6:30 PM';}if(!db.gallery)db.gallery=[];if(!db.slides)db.slides=[['1','Teacher reading with children around the classroom table'],['2','Story time in the classroom'],['3','Activity corner with learning toys'],['4','Children playing on rockers and slide in the play area'],['5','Kids enjoying the indoor play area'],['6','Colourful indoor play zone with slide and rockers']].map(([n,c])=>({id:'s'+n,src:'/static/slideshow/slide-'+n+'.jpg',photo:'',caption:c}));if(!db.daycare.officeTime)db.daycare.officeTime='Monday to Saturday, 9:00 AM to 4:00 PM';if(!db.holidays)db.holidays=[{id:'h1',date:'2026-11-09',title:'[PLACEHOLDER] Diwali holidays',note:'Sample only - please replace from Admin, Holidays tab'},{id:'h2',date:'2026-12-25',title:'[PLACEHOLDER] Christmas',note:'Sample only - please replace'},{id:'h3',date:'2027-01-26',title:'[PLACEHOLDER] Republic Day',note:'Sample only - please replace'}];delete db.notes;if(!db.attendance)db.attendance={};delete db.events;delete db.leaves;delete db.log;if(!db.staffNotes)db.staffNotes=[];if(!db.lost)db.lost=[];delete db.receipts;delete db.fees;if(!db.about||/PLACEHOLDER/.test(db.about.body||'')){db.about={title:'About us',body:"Aarunya Kids Preschool is a small, caring preschool in Nizampet, Hyderabad. Our motto is First Light of Learning: we help little ones take their first happy steps into learning in a warm and safe place.\n\nWith a decade of experience in caring for young children, the school is run with deep patience and attention. Our trained didis and staff know how to handle little ones kindly — settling them when they are new, guiding play, and making each day feel calm and friendly.\n\nOur school is managed by a dedicated team of staff trained in the field of education. Each teacher understands how young children grow, learn and feel, and brings that knowledge into the classroom every day. From planning age-appropriate activities to gently noticing each child's needs, our team works together so that every little one feels confident, cared for and ready to learn.\n\nLearning here is playful and hands-on. Children explore with songs, stories, games, art and lots of props and equipment, so they have fun and also learn by doing. We use simple preschool methods that suit this age: learning through play, movement, sensory activities and guided group time, so little minds grow without pressure.\n\nWe also share our culture with care. Children take part in festivals and celebrations such as Guru Purnima and other festivals, so they grow up with warmth, respect and a sense of Sanskriti alongside their everyday play and learning.\n\nParents are always welcome to visit, ask questions and see how their child spends the day. We are a small school with one close group of children, so every family is known and looked after."};}if(db.about&&/hindu/i.test(db.about.body||'')){db.about.body=db.about.body.replace(/\s*\bhindu\b/gi,'');}save();
{const au=db.users.find(u=>u.role==='admin');if(au){if(process.env.ADMIN_USERNAME)au.username=process.env.ADMIN_USERNAME;else if(au.username==='admin')au.username='Principal';if(process.env.ADMIN_PASSWORD&&!bcrypt.compareSync(process.env.ADMIN_PASSWORD,au.pass))au.pass=bcrypt.hashSync(process.env.ADMIN_PASSWORD,8);save();}}
const id=()=>crypto.randomBytes(5).toString('hex');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=express();app.use(express.urlencoded({extended:true}));app.use('/static',express.static(path.join(__dirname,'public')));
if(process.env.NODE_ENV==='production'&&!process.env.SESSION_SECRET)throw new Error('Set SESSION_SECRET');
app.set('trust proxy',1);
const SHORT=12*3600e3,LONG=10*365*24*3600e3,SF=path.join(DATA,'data/sessions.json');
class FileStore extends session.Store{constructor(){super();try{this.m=JSON.parse(fs.readFileSync(SF))}catch{this.m={}}}
 w(){const n=Date.now();for(const k in this.m)if(this.m[k].exp<n)delete this.m[k];fs.writeFile(SF,JSON.stringify(this.m),()=>{})}
 get(id,cb){const r=this.m[id];cb(null,r&&r.exp>Date.now()?r.s:null)}
 set(id,ss,cb){this.m[id]={s:ss,exp:Date.now()+(ss.cookie&&ss.cookie.maxAge?ss.cookie.maxAge:SHORT)};this.w();cb&&cb()}
 destroy(id,cb){delete this.m[id];this.w();cb&&cb()}
 touch(id,ss,cb){this.set(id,ss,cb)}}
const SECRET=process.env.SESSION_SECRET||(()=>{const f=path.join(DATA,'data/.devsecret');try{return fs.readFileSync(f,'utf8')}catch{const v=crypto.randomBytes(32).toString('hex');fs.writeFileSync(f,v);return v}})();
app.use(session({store:new FileStore(),rolling:true,secret:SECRET,resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production'}}));
const upload=multer({dest:UP,limits:{fileSize:5e6},fileFilter:(r,f,cb)=>cb(null,/^image\//.test(f.mimetype))});
const me=r=>db.users.find(u=>u.id===r.session.uid);
const need=role=>(q,s,n)=>{const u=me(q);if(!u||(role&&u.role!==role))return s.redirect('/login');q.user=u;n();};
// uniform photos are public; kid photos only for admin or that kid's parent
app.get('/photo/:f',(q,s)=>{const f=path.basename(q.params.f);const kid=db.kids.find(k=>k.photo===f);
 if(kid){const u=me(q);if(!u||(u.role!=='admin'&&kid.parentId!==u.id))return s.sendStatus(403);}
 else if(!db.uniforms.some(x=>x.photo===f)&&!(db.gallery||[]).some(x=>x.photo===f))return s.sendStatus(404);s.sendFile(path.join(UP,f));});
const page=(q,title,body)=>{const u=me(q);return`<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>${e(title)} | Aarunya Kids Preschool, Nizampet, Hyderabad</title>${(()=>{const base=q.protocol+'://'+q.get('host'),d='Aarunya Kids Preschool - First Light of Learning. Preschool and daycare in Nizampet, Hyderabad. School 8:45 AM to 3:30 PM, Daycare 8:30 AM to 6:30 PM.';return `<meta name=description content="${e(d)}"><meta property=og:type content=website><meta property=og:site_name content="Aarunya Kids Preschool"><meta property=og:title content="${e(title)} | Aarunya Kids Preschool"><meta property=og:description content="${e(d)}"><meta property=og:url content="${e(base+q.originalUrl.split('?')[0])}"><meta property=og:image content="${e(base)}/static/og.png"><meta property=og:image:width content=1200><meta property=og:image:height content=630><meta name=twitter:card content=summary_large_image><link rel=icon href=/static/logo.png>`})()}<link rel=stylesheet href=/static/style.css></head><body class="${u?'in':'pub'}">
<header><a href=/ class=brand><img src=/static/logo.png alt="Aarunya Kids Preschool"><span class=sr-only><b>Aarunya Kids Preschool</b><small>First Light of Learning</small></span></a>
<input type=checkbox id=mnu class=mnu hidden><label for=mnu class=burger aria-label=Menu><span></span><span></span><span></span> Menu</label><nav>${u&&u.role==='parent'?`<span class=navlbl>For parents</span><a href=/parent#today class=par>Today</a><a href=/parent#kids class=par>My Kids</a><span class=navlbl>School</span>`:''}<a href=/>Home</a><a href=/about>About</a><a href=/#find>Find us</a>${u?`<a href=/uniform>Uniform</a><a href=/gallery>Gallery</a><a href=/announcements>News</a><a href=/daycare>Daycare</a><a href=/calendar>Holidays</a>`:''}${u?(u.role==='admin'?'<a href=/admin class=hi>Admin</a>':'')+'<a href=/logout class=out>Log out</a>':'<a href=/login class=hi>Login</a>'}</nav></header><main>${body}</main>
<footer><p class=noprint><a href=/help>Help and guide</a></p><div class=faddr>${e(addr())}</div><div class=faddr>Phone: ${phoneLinks()}</div><div class=faddr>Email: ${mail()}</div>${follow()}Prototype – all <b>[PLACEHOLDER]</b> content must be replaced by the school. Instagram: @aarunya_kids_preschool · <a href="${YT}" target=_blank rel=noopener>YouTube: Aarunya Kids Preschool</a></footer></body></html>`};
const ph=p=>p?`<img class=pic src="/photo/${e(p)}">`:`<div class="pic none"><br>Photo coming soon</div>`;
app.get('/',(q,s)=>s.send(page(q,'Home',`${(()=>{const u=me(q);return u&&u.role==='parent'?`<div class=parentstrip><h2>Hi ${e(u.name)}!</h2>${summary(u)}<p><a class="btn b2 big" href=/parent#kids>Open My Kids</a></p></div>`:''})()}<section class=hero2><div class=htext><p class=kicker>Preschool and Daycare, Nizampet, Hyderabad</p><h1>Welcome to Aarunya Kids Preschool</h1><p class=tag>First Light of Learning</p><p>A warm, caring place where little ones learn through play, songs, activities and celebrations.</p><div class=cta><a class="btn b1" href=/daycare#enquiry>Enquire now</a><a class="btn ghost" href=/daycare>Book Daycare</a><a class="btn ghost" href=#find>Find us</a></div></div><div class=hlogo><img src=/static/logo.png alt="Aarunya Kids Preschool logo"></div></section>${slider()}<script src=/static/slideshow.js defer></script>
<section class=aboutsec><div><p class=kicker>About us</p><h2>${e(db.about.title||'About us')}</h2>${(()=>{const raw=db.about.body||'',ph=/PLACEHOLDER/.test(raw),t=raw.replace(/^\[PLACEHOLDER[^\]]*\]\s*/,'').trim(),x=t.length>280?t.slice(0,t.lastIndexOf(' ',280))+'...':t;return (ph?'<span class=sample>Sample text</span>':'')+`<p>${e(x)}</p>`})()}<a class="btn b2" href=/about>View more</a></div><div class=qlinks><a href=/uniform><b>Uniform</b><span>What children wear</span></a><a href=/gallery><b>Gallery</b><span>Moments from school</span></a><a href=/announcements><b>News</b><span>Latest updates</span></a><a href=/daycare><b>Daycare</b><span>Timings and booking</span></a></div></section>
<section class=enqband><div><h2>Looking for a preschool for your child?</h2><p>Visit us in Nizampet or send an enquiry. We will call you back.</p></div><a class="btn b1 big" href=/daycare#enquiry>Send an enquiry</a></section>
<section class=homesec id=find><p class=kicker>Visit us</p><h2 class=sech>Find us in Nizampet</h2>${findUs()}</section>${timesBox()}<div class="card hhol"><h2>Upcoming holidays</h2>${upList(upcoming(3,365))}<p><a class="btn b2" href=/calendar>View full calendar</a></p></div>
<section class=homesec><p class=kicker>Gallery</p><h2 class=sech>Life at Aarunya</h2>${db.gallery.length?`<div class=gallery>${db.gallery.slice(0,6).map(g=>`<figure><a href="/photo/${e(g.photo)}" target=_blank><img src="/photo/${e(g.photo)}" alt="${e(g.caption||'School activity photo')}" loading=lazy></a>${g.caption?`<figcaption>${e(g.caption)}</figcaption>`:''}</figure>`).join('')}</div>`:'<div class="card note"><b>Photos coming soon.</b> The school will add pictures of activities and celebrations here.</div>'}<p><a class="btn b2" href=/gallery>View full gallery</a></p></section>
<section class=homesec><p class=kicker>Videos</p><h2 class=sech>Celebrations and activities</h2><div class=grid>${HOMEVIDS.map(([v,t])=>`<div class=card><div class=vid><iframe src="https://www.youtube-nocookie.com/embed/${v}" title="${e(t)}" allowfullscreen loading=lazy></iframe></div><h3>${e(t)}</h3></div>`).join('')}</div><p><a class="btn yt" href="${YT}" target=_blank rel=noopener>See all videos on YouTube</a></p></section><h2>Latest news</h2>${news().slice(0,3).map(newsCard).join('')||noNews}`)));
app.get('/uniform',(q,s)=>s.send(page(q,'Uniform',`<h1>Uniform</h1><div class="card note"><b>Photos coming soon.</b> We are adding a picture of our school uniform. For questions, please call or email us.</div>${me(q)&&me(q).role==='admin'?'<div class="card note"><b>Admin tip:</b> add or change uniform photos in <a href=/admin?t=uniform>Admin, Uniform tab</a>.</div>':''}<div class=grid>${(db.uniforms.length?db.uniforms:[{name:'Uniform',desc:'Details coming soon.',photo:''}]).map(u=>`<div class=card>${u.photo?`<img class=pic src="/photo/${e(u.photo)}">`:ph('')}<h3>${e(u.name)}</h3><p>${e(u.desc)}</p></div>`).join('')}</div>`)));
app.get('/announcements',(q,s)=>s.send(page(q,'News',`<h1>Announcements</h1>${news().map(newsCard).join('')||noNews}`)));
