 if(t==='news')h+=`<form method=post action=/admin/news class=card><h2>Add news</h2><label>Title<input name=title required></label><label>Message<textarea name=body></textarea></label><label>Pin to top?<select name=pinned><option value=no>No</option><option value=yes>Yes, keep at the top</option></select></label><button class="btn b1">Add</button></form>`+news().map(a=>`<form method=post action=/admin/news/${a.id} class=card><label>Title<input name=title value="${e(a.title)}"></label><label>Message<textarea name=body>${e(a.body)}</textarea></label><label>Pin to top?<select name=pinned><option value=no>No</option><option value=yes ${a.pinned==='yes'?'selected':''}>Yes, keep at the top</option></select></label><p>Posted: ${nice(a.date)}</p><button class="btn b3">Save</button> <button class="btn del" name=del value=1>Delete</button></form>`).join('');
